static int balanced_make(const std::vector<int>&xs,int lo,int hi,int&next,std::vector<int32_t>&a,std::vector<int32_t>&b){if(hi-lo==1)return xs[lo];int mid=(lo+hi)/2,l=balanced_make(xs,lo,mid,next,a,b),r=balanced_make(xs,mid,hi,next,a,b),u=next++;a[u]=l;b[u]=r;return u;}
static int group(int lo,int hi,bool balanced,int&next,std::vector<int32_t>&a,std::vector<int32_t>&b){std::vector<int>xs(hi-lo);std::iota(xs.begin(),xs.end(),lo);if(balanced)return balanced_make(xs,0,xs.size(),next,a,b);int u=lo;for(int x=lo+1;x<hi;x++){int v=next++;a[v]=u;b[v]=x;u=v;}return u;}

static double cpu_jc(int x,int y,const std::vector<uint64_t>&seq){if(x==y)return 0;int matches=0;for(int w=0;w<25;w++){uint64_t m=(seq[x*125+w]&seq[y*125+w])|(seq[x*125+25+w]&seq[y*125+25+w]);matches+=__builtin_popcountll(m);}double p=std::min(.74,(1600.-matches)/1600.);return -.75*log(1.-(4./3.)*p);}
int main(){for(int big:{0,1}){int A=big?4096:9,N=big?4102:17,K=N-A+1,cap=big?64:0;std::vector<int32_t>a(2*N-1),b(2*N-1);int next=N,rA=group(0,A,big,next,a,b),rG=group(A+2,N,big,next,a,b);int left=next++;a[left]=rA;b[left]=A;int right=next++;a[right]=A+1;b[right]=rG;int root=next++;a[root]=left;b[root]=right;std::vector<int32_t>ord,par,cnt,rep,ls,offs={0};std::vector<float>ws;compute_tree_summaries_blind(a.data(),b.data(),N,ord,par,cnt,rep);compute_clade_dyadic_profile(rA,N,a.data(),b.data(),rep.data(),cap,ls,ws);offs.push_back(ls.size());for(int x=A;x<N;x++){ls.push_back(x);ws.push_back(1);offs.push_back(ls.size());}
std::mt19937_64 gen(2309);std::vector<uint64_t>seq((size_t)N*125,0);for(int x=0;x<N;x++)for(int w=0;w<25;w++){uint64_t mask=gen()&gen();seq[x*125+w]=~mask;seq[x*125+25+w]=mask;seq[x*125+100+w]=~0ULL;}uint64_t*ds;int32_t *doff,*dl;float *dw,*dD;CUDA_CHECK(cudaMalloc(&ds,seq.size()*sizeof(uint64_t)));CUDA_CHECK(cudaMalloc(&doff,offs.size()*sizeof(int32_t)));CUDA_CHECK(cudaMalloc(&dl,ls.size()*sizeof(int32_t)));CUDA_CHECK(cudaMalloc(&dw,ws.size()*sizeof(float)));CUDA_CHECK(cudaMalloc(&dD,K*K*sizeof(float)));CUDA_CHECK(cudaMemcpy(ds,seq.data(),seq.size()*sizeof(uint64_t),cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpy(doff,offs.data(),offs.size()*sizeof(int32_t),cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpy(dl,ls.data(),ls.size()*sizeof(int32_t),cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpy(dw,ws.data(),ws.size()*sizeof(float),cudaMemcpyHostToDevice));dim3 block(16,16),grid((K+15)/16,(K+15)/16);k_build_real_seq_condensed_D<<<grid,block>>>(K,25,doff,dl,dw,ds,dD);std::vector<float>D(K*K);CUDA_CHECK(cudaMemcpy(D.data(),dD,K*K*sizeof(float),cudaMemcpyDeviceToHost));double maxerr=0;for(int i=0;i<K;i++)for(int j=0;j<K;j++){double expected=0;if(i!=j)for(int p=offs[i];p<offs[i+1];p++)for(int q=offs[j];q<offs[j+1];q++)expected+=(double)ws[p]*ws[q]*cpu_jc(ls[p],ls[q],seq);maxerr=fmax(maxerr,fabs(D[i*K+j]-expected));}printf("actual sequence CUDA kernel N=%d K=%d cap=%d condensed_entries=%d max_error_vs_weighted_CPU_JC=%.17g\n",N,K,cap,offs[1],maxerr);if(maxerr>1e-6)return 1;cudaFree(ds);cudaFree(doff);cudaFree(dl);cudaFree(dw);cudaFree(dD);}return 0;}
